'use strict';

var constants = require('@toruslabs/constants');

/** Type guard: narrows network to legacy network type for LEGACY_NETWORKS_ROUTE_MAP / METADATA_MAP lookups. */
function isLegacyNetwork(network) {
  return Object.prototype.hasOwnProperty.call(constants.LEGACY_NETWORKS_ROUTE_MAP, network);
}

exports.isLegacyNetwork = isLegacyNetwork;
